html:
{%- set emp = frappe.db.get_value("Employee", doc.employee,
    ["employee_name","designation","department"], as_dict=True) or {} %}
{%- set mgr = frappe.db.get_value("Employee", doc.manager,
    ["employee_name","designation"], as_dict=True) or {} %}
<!DOCTYPE html><html><head><meta charset="UTF-8"/>
<style>
* { margin:0; padding:0; box-sizing:border-box; }
body { font-family: Calibri, Arial, sans-serif; font-size: 11pt; color: #1E293B; }
.page-header { background: linear-gradient(135deg, #1E2D5A 0%, #5B2D8E 100%);
  padding: 24px 32px; color: white; display: flex;
  justify-content: space-between; align-items: flex-start; }
.brand { font-size: 18pt; font-weight: 900; letter-spacing: -1px; }
.brand-sub { font-size: 8pt; color: rgba(255,255,255,.65); margin-top: 2px; }
.doc-meta { text-align: right; }
.doc-meta h1 { font-size: 14pt; font-weight: 800; }
.doc-meta p  { font-size: 8pt; color: rgba(255,255,255,.7); margin-top: 3px; }
.emp-band { background:#F1F5F9; border-left:5px solid #5B2D8E;
  padding:12px 32px; display:flex; gap:28px; flex-wrap:wrap; }
.ef .el { font-size:8pt; font-weight:700; color:#64748B;
  text-transform:uppercase; letter-spacing:.4px; }
.ef .ev { font-size:10pt; font-weight:600; margin-top:2px; }
.sec { padding:14px 32px; border-bottom:1px solid #E5E7EB; }
.sec-h { font-size:10pt; font-weight:800; color:#5B2D8E; text-transform:uppercase;
  letter-spacing:.5px; border-bottom:2px solid #5B2D8E; padding-bottom:5px;
  margin-bottom:10px; }
table { width:100%; border-collapse:collapse; margin:6px 0; }
th { background:#1E2D5A; color:white; padding:7px 10px;
  font-size:8.5pt; font-weight:700; text-align:left; }
td { padding:7px 10px; font-size:9.5pt; border-bottom:1px solid #F1F5F9; }
tr:nth-child(even) td { background:#F8FAFC; }
.nb { background:#F8FAFC; border:1px solid #E2E8F0; border-radius:5px;
  padding:10px 14px; min-height:50px; font-size:9.5pt; line-height:1.6;
  white-space:pre-wrap; }
.pill { display:inline-block; padding:2px 10px; border-radius:99px;
  font-weight:700; font-size:8.5pt; }
.green { background:#D1FAE5; color:#065F46; }
.blue  { background:#DBEAFE; color:#1D4ED8; }
.amber { background:#FEF3C7; color:#92400E; }
.red   { background:#FEE2E2; color:#991B1B; }
.purple{ background:#EDE9FE; color:#5B21B6; }
.score-hero { text-align:center; background:#F0FDF4;
  border:2px solid #6EE7B7; border-radius:10px; padding:14px; margin:8px 0; }
.score-num { font-size:30pt; font-weight:900; color:#059669; }
.score-lbl { font-size:9pt; color:#6B7280; }
.sig-row { display:flex; gap:28px; margin-top:6px; }
.sig-box { flex:1; }
.sig-line { border-bottom:1.5px solid #1E2D5A; margin-top:28px; margin-bottom:5px; }
.sig-name { font-size:8.5pt; color:#6B7280; }
.page-footer { background:#F8FAFC; border-top:1px solid #E2E8F0;
  padding:8px 32px; display:flex; justify-content:space-between;
  font-size:7.5pt; color:#94A3B8; }

.status-banner { padding:12px 32px; font-size:10pt; font-weight:700;
  display:flex; align-items:center; gap:10px; }
.status-active  { background:#FEF3C7; color:#92400E; border-left:5px solid #F59E0B; }
.status-passed  { background:#D1FAE5; color:#065F46; border-left:5px solid #059669; }
.status-failed  { background:#FEE2E2; color:#991B1B; border-left:5px solid #DC2626; }
.date-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:10px; margin:8px 0; }
.dc { background:#F8FAFC; border:1px solid #E2E8F0; border-radius:6px; padding:10px; }
.dc .dl { font-size:8pt; font-weight:700; color:#64748B; text-transform:uppercase; }
.dc .dv { font-size:10pt; font-weight:600; margin-top:3px; }
</style></head><body>

<div class="page-header">
  <div><div class="brand">Ecclesia</div><div class="brand-sub">Human Capital Management</div></div>
  <div class="doc-meta"><h1>Performance Improvement Plan</h1>
    <p>{{ doc.name }} | {{ frappe.format_date(doc.creation) }}</p></div>
</div>

<div class="status-banner status-{{ doc.status|lower if doc.status in ('Active','Passed','Failed') else 'active' }}">
  ⚡ PIP Status: {{ doc.status }}
  {% if doc.status == "Active" %} — Plan currently in effect{% endif %}
  {% if doc.status == "Passed" %} — Employee has met the required standards{% endif %}
  {% if doc.status == "Failed" %} — Performance targets not achieved{% endif %}
</div>

<div class="emp-band">
  <div class="ef"><div class="el">Employee</div><div class="ev">{{ emp.employee_name or doc.employee }}</div></div>
  <div class="ef"><div class="el">Designation</div><div class="ev">{{ emp.designation or "—" }}</div></div>
  <div class="ef"><div class="el">Department</div><div class="ev">{{ emp.department or "—" }}</div></div>
  <div class="ef"><div class="el">Line Manager</div><div class="ev">{{ mgr.employee_name or doc.manager }}</div></div>
</div>

<div class="sec">
  <div class="sec-h">📅 Plan Timeline</div>
  <div class="date-grid">
    <div class="dc"><div class="dl">Start Date</div><div class="dv">{{ frappe.format_date(doc.start_date) }}</div></div>
    <div class="dc"><div class="dl">End Date</div><div class="dv">{{ frappe.format_date(doc.end_date) }}</div></div>
    <div class="dc"><div class="dl">Review Frequency</div><div class="dv">{{ doc.review_frequency or "Weekly" }}</div></div>
    <div class="dc"><div class="dl">Performance Cycle</div><div class="dv">{{ doc.performance_cycle or "—" }}</div></div>
  </div>
</div>

{% if doc.performance_concern %}
<div class="sec"><div class="sec-h">⚠️ Performance Concern</div>
  <div class="nb" style="background:#FEF2F2;border-color:#FECACA;">{{ doc.performance_concern }}</div></div>
{% endif %}

{% if doc.pip_objectives %}
<div class="sec">
  <div class="sec-h">🎯 PIP Objectives</div>
  <table><thead><tr><th>Objective</th><th>Success Criteria</th><th>Target Date</th><th>Status</th></tr></thead>
  <tbody>{% for r in doc.pip_objectives %}<tr>
    <td><b>{{ r.objective }}</b></td>
    <td>{{ r.success_criteria or "—" }}</td>
    <td>{{ frappe.format_date(r.target_date) if r.target_date else "—" }}</td>
    <td><span class="pill {% if r.status=='Achieved' %}green{% elif r.status=='Not Achieved' %}red{% else %}amber{% endif %}">{{ r.status or "Pending" }}</span></td>
  </tr>{% endfor %}</tbody></table>
</div>
{% endif %}

{% if doc.weekly_checkins %}
<div class="sec">
  <div class="sec-h">📋 Weekly Check-in Log</div>
  <table><thead><tr><th>Date</th><th>Manager Notes</th><th>Employee Response</th><th>Progress</th></tr></thead>
  <tbody>{% for r in doc.weekly_checkins %}<tr>
    <td>{{ frappe.format_date(r.checkin_date) if r.checkin_date else "—" }}</td>
    <td>{{ r.manager_notes or "—" }}</td>
    <td>{{ r.employee_response or "—" }}</td>
    <td><span class="pill {% if r.progress_rating=='On Track' %}green{% elif r.progress_rating=='At Risk' %}amber{% else %}red{% endif %}">{{ r.progress_rating or "—" }}</span></td>
  </tr>{% endfor %}</tbody></table>
</div>
{% endif %}

{% if doc.final_outcome %}
<div class="sec"><div class="sec-h">📌 Final Outcome</div>
  <div class="nb">{{ doc.final_outcome }}</div>
  {% if doc.outcome_notes %}<div class="nb" style="margin-top:8px;">{{ doc.outcome_notes }}</div>{% endif %}
</div>
{% endif %}

{% if doc.support_resources %}
<div class="sec"><div class="sec-h">🤝 Support & Resources</div>
  <div class="nb">{{ doc.support_resources }}</div></div>
{% endif %}

<div class="sec"><div class="sec-h">✍️ Acknowledgements</div>
  <p style="font-size:9pt;color:#4B5563;margin-bottom:14px">
    By signing below, all parties confirm they have read and understood this Performance Improvement Plan
    and are committed to supporting the employee through this process.</p>
  <div class="sig-row">
    <div class="sig-box"><div class="sig-line"></div>
      <div class="sig-name"><b>{{ emp.employee_name or doc.employee }}</b><br>Employee | Date: ____________</div></div>
    <div class="sig-box"><div class="sig-line"></div>
      <div class="sig-name"><b>{{ mgr.employee_name or doc.manager }}</b><br>Line Manager | Date: ____________</div></div>
    <div class="sig-box"><div class="sig-line"></div>
      <div class="sig-name"><b>HR Representative</b><br>Verified By | Date: ____________</div></div>
  </div>
</div>

<div class="page-footer">
  <span>Ecclesia HR · Value Impacts Consulting</span>
  <span>{{ doc.name }} | Printed: {{ frappe.format_date(frappe.utils.nowdate()) }}</span>
  <span>STRICTLY CONFIDENTIAL</span>
</div>
</body></html>
